import { createRoute, z } from '@hono/zod-openapi'

const LicenseResourceCommitmentSchema = z
  .object({
    amount: z
      .string()
      .exactOptional()
      .openapi({ description: 'The number of licenses purchased.' }),
    coresPerLicense: z
      .string()
      .exactOptional()
      .openapi({
        description: 'Specifies the core range of the instance for which this license applies.',
      }),
    license: z.string().exactOptional().openapi({ description: 'Any applicable license URI.' }),
  })
  .openapi({ description: 'Commitment for a particular license resource.', required: [] })
  .openapi('LicenseResourceCommitment')

const ReservationSchema: z.ZodType<ReservationType> = z
  .lazy(() =>
    z
      .object({
        aggregateReservation: AllocationAggregateReservationSchema.exactOptional().openapi({
          description: 'Reservation for aggregated resources, providing shape flexibility.',
        }),
        commitment: z
          .string()
          .exactOptional()
          .openapi({
            description:
              '[Output Only] Full or partial URL to a parent commitment. This field displays for reservations that are tied to a commitment.',
          }),
        creationTimestamp: z
          .string()
          .exactOptional()
          .openapi({ description: '[Output Only] Creation timestamp in RFC3339 text format.' }),
        description: z
          .string()
          .exactOptional()
          .openapi({
            description:
              'An optional description of this resource. Provide this property when you create the resource.',
          }),
        id: z
          .string()
          .exactOptional()
          .openapi({
            description:
              '[Output Only] The unique identifier for the resource. This identifier is defined by the server.',
          }),
        kind: z
          .string()
          .default('compute#reservation')
          .exactOptional()
          .openapi({
            description:
              '[Output Only] Type of the resource. Always compute#reservations for reservations.',
          }),
        name: z
          .string()
          .regex(/[a-z](?:[-a-z0-9]{0,61}[a-z0-9])?/)
          .exactOptional()
          .openapi({
            description:
              'The name of the resource, provided by the client when initially creating the resource. The resource name must be 1-63 characters long, and comply with RFC1035. Specifically, the name must be 1-63 characters long and match the regular expression `[a-z]([-a-z0-9]*[a-z0-9])?` which means the first character must be a lowercase letter, and all following characters must be a dash, lowercase letter, or digit, except the last character, which cannot be a dash.',
          }),
        resourcePolicies: z
          .record(z.string(), z.string())
          .exactOptional()
          .openapi({
            description:
              'Resource policies to be added to this reservation. The key is defined by user, and the value is resource policy url. This is to define placement policy with reservation.',
          }),
        resourceStatus: AllocationResourceStatusSchema.exactOptional().openapi({
          description: '[Output Only] Status information for Reservation resource.',
        }),
        satisfiesPzs: z
          .boolean()
          .exactOptional()
          .openapi({ description: '[Output Only] Reserved for future use.' }),
        selfLink: z
          .string()
          .exactOptional()
          .openapi({
            description: '[Output Only] Server-defined fully-qualified URL for this resource.',
          }),
        shareSettings: ShareSettingsSchema.exactOptional().openapi({
          description:
            'Specify share-settings to create a shared reservation. This property is optional. For more information about the syntax and options for this field and its subfields, see the guide for creating a shared reservation.',
        }),
        specificReservation: AllocationSpecificSKUReservationSchema.exactOptional().openapi({
          description: 'Reservation for instances with specific machine shapes.',
        }),
        specificReservationRequired: z
          .boolean()
          .exactOptional()
          .openapi({
            description:
              'Indicates whether the reservation can be consumed by VMs with affinity for "any" reservation. If the field is set, then only VMs that target the reservation by name can consume from this reservation.',
          }),
        status: z
          .enum(['CREATING', 'DELETING', 'INVALID', 'READY', 'UPDATING'])
          .exactOptional()
          .openapi({ description: '[Output Only] The status of the reservation.' }),
        zone: z
          .string()
          .exactOptional()
          .openapi({
            description:
              'Zone in which the reservation resides. A zone must be provided if the reservation is created within a commitment.',
          }),
      })
      .openapi({
        description:
          'Represents a reservation resource. A reservation ensures that capacity is held in a specific zone even if the reserved VMs are not running. For more information, read Reserving zonal resources.',
        required: [],
      }),
  )
  .openapi('Reservation')

const ResourceCommitmentSchema = z
  .object({
    acceleratorType: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Name of the accelerator type resource. Applicable only when the type is ACCELERATOR.',
      }),
    amount: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The amount of the resource purchased (in a type-dependent unit, such as bytes). For vCPUs, this can just be an integer. For memory, this must be provided in MB. Memory must be a multiple of 256 MB, with up to 6.5GB of memory per every vCPU.',
      }),
    type: z
      .enum(['ACCELERATOR', 'LOCAL_SSD', 'MEMORY', 'UNSPECIFIED', 'VCPU'])
      .exactOptional()
      .openapi({
        description:
          'Type of resource for which this commitment applies. Possible values are VCPU, MEMORY, LOCAL_SSD, and ACCELERATOR.',
      }),
  })
  .openapi({
    description:
      'Commitment for a particular resource (a Commitment is composed of one or more of these).',
    required: [],
  })
  .openapi('ResourceCommitment')

type CommitmentType = {
  autoRenew?: boolean
  category?: 'CATEGORY_UNSPECIFIED' | 'LICENSE' | 'MACHINE'
  creationTimestamp?: string
  description?: string
  endTimestamp?: string
  existingReservations?: string[]
  id?: string
  kind?: string
  licenseResource?: z.infer<typeof LicenseResourceCommitmentSchema>
  mergeSourceCommitments?: string[]
  name?: string
  plan?: 'INVALID' | 'THIRTY_SIX_MONTH' | 'TWELVE_MONTH'
  region?: string
  reservations?: z.infer<typeof ReservationSchema>[]
  resources?: z.infer<typeof ResourceCommitmentSchema>[]
  selfLink?: string
  splitSourceCommitment?: string
  startTimestamp?: string
  status?: 'ACTIVE' | 'CANCELLED' | 'CREATING' | 'EXPIRED' | 'NOT_YET_ACTIVE'
  statusMessage?: string
  type?:
    | 'ACCELERATOR_OPTIMIZED'
    | 'ACCELERATOR_OPTIMIZED_A3'
    | 'COMPUTE_OPTIMIZED'
    | 'COMPUTE_OPTIMIZED_C2D'
    | 'COMPUTE_OPTIMIZED_C3'
    | 'COMPUTE_OPTIMIZED_C3D'
    | 'COMPUTE_OPTIMIZED_H3'
    | 'GENERAL_PURPOSE'
    | 'GENERAL_PURPOSE_E2'
    | 'GENERAL_PURPOSE_N2'
    | 'GENERAL_PURPOSE_N2D'
    | 'GENERAL_PURPOSE_T2D'
    | 'GRAPHICS_OPTIMIZED'
    | 'MEMORY_OPTIMIZED'
    | 'MEMORY_OPTIMIZED_M3'
    | 'STORAGE_OPTIMIZED_Z3'
    | 'TYPE_UNSPECIFIED'
}

const GRPCHealthCheckSchema = z
  .object({
    grpcServiceName: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The gRPC service name for the health check. This field is optional. The value of grpc_service_name has the following meanings by convention: - Empty service_name means the overall status of all services at the backend. - Non-empty service_name means the health of that gRPC service, as defined by the owner of the service. The grpc_service_name can only be ASCII.',
      }),
    port: z
      .int32()
      .exactOptional()
      .openapi({
        description:
          'The TCP port number to which the health check prober sends packets. Valid values are 1 through 65535.',
      }),
    portName: z.string().exactOptional().openapi({ description: 'Not supported.' }),
    portSpecification: z
      .enum(['USE_FIXED_PORT', 'USE_NAMED_PORT', 'USE_SERVING_PORT'])
      .exactOptional()
      .openapi({
        description:
          "Specifies how a port is selected for health checking. Can be one of the following values: USE_FIXED_PORT: Specifies a port number explicitly using the port field in the health check. Supported by backend services for passthrough load balancers and backend services for proxy load balancers. Not supported by target pools. The health check supports all backends supported by the backend service provided the backend can be health checked. For example, GCE_VM_IP network endpoint groups, GCE_VM_IP_PORT network endpoint groups, and instance group backends. USE_NAMED_PORT: Not supported. USE_SERVING_PORT: Provides an indirect method of specifying the health check port by referring to the backend service. Only supported by backend services for proxy load balancers. Not supported by target pools. Not supported by backend services for passthrough load balancers. Supports all backends that can be health checked; for example, GCE_VM_IP_PORT network endpoint groups and instance group backends. For GCE_VM_IP_PORT network endpoint group backends, the health check uses the port number specified for each endpoint in the network endpoint group. For instance group backends, the health check uses the port number determined by looking up the backend service's named port in the instance group's list of named ports.",
      }),
  })
  .openapi({ required: [] })
  .openapi('GRPCHealthCheck')

const HTTP2HealthCheckSchema = z
  .object({
    host: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The value of the host header in the HTTP/2 health check request. If left empty (default value), the host header is set to the destination IP address to which health check packets are sent. The destination IP address depends on the type of load balancer. For details, see: https://cloud.google.com/load-balancing/docs/health-check-concepts#hc-packet-dest',
      }),
    port: z
      .int32()
      .exactOptional()
      .openapi({
        description:
          'The TCP port number to which the health check prober sends packets. The default value is 443. Valid values are 1 through 65535.',
      }),
    portName: z.string().exactOptional().openapi({ description: 'Not supported.' }),
    portSpecification: z
      .enum(['USE_FIXED_PORT', 'USE_NAMED_PORT', 'USE_SERVING_PORT'])
      .exactOptional()
      .openapi({
        description:
          "Specifies how a port is selected for health checking. Can be one of the following values: USE_FIXED_PORT: Specifies a port number explicitly using the port field in the health check. Supported by backend services for passthrough load balancers and backend services for proxy load balancers. Not supported by target pools. The health check supports all backends supported by the backend service provided the backend can be health checked. For example, GCE_VM_IP network endpoint groups, GCE_VM_IP_PORT network endpoint groups, and instance group backends. USE_NAMED_PORT: Not supported. USE_SERVING_PORT: Provides an indirect method of specifying the health check port by referring to the backend service. Only supported by backend services for proxy load balancers. Not supported by target pools. Not supported by backend services for passthrough load balancers. Supports all backends that can be health checked; for example, GCE_VM_IP_PORT network endpoint groups and instance group backends. For GCE_VM_IP_PORT network endpoint group backends, the health check uses the port number specified for each endpoint in the network endpoint group. For instance group backends, the health check uses the port number determined by looking up the backend service's named port in the instance group's list of named ports.",
      }),
    proxyHeader: z
      .enum(['NONE', 'PROXY_V1'])
      .exactOptional()
      .openapi({
        description:
          'Specifies the type of proxy header to append before sending data to the backend, either NONE or PROXY_V1. The default is NONE.',
      }),
    requestPath: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The request path of the HTTP/2 health check request. The default value is /.',
      }),
    response: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Creates a content-based HTTP/2 health check. In addition to the required HTTP 200 (OK) status code, you can configure the health check to pass only when the backend sends this specific ASCII response string within the first 1024 bytes of the HTTP response body. For details, see: https://cloud.google.com/load-balancing/docs/health-check-concepts#criteria-protocol-http',
      }),
  })
  .openapi({ required: [] })
  .openapi('HTTP2HealthCheck')

